const items = $input.all();
const addressItems = [];

for (const item of items) {
  const data = item.json;

  // KANDIDAT mit Distanz-Einstellung
  if (data.property_geburtsdatum && data.property_wohnadresse && data.property_wohnadresse.trim() !== '') {
    // DEBUG: Zeige ALLE Felder
    const allFields = Object.keys(data).filter(k => k.startsWith('property_'));
    console.log(`\n=== Kandidat ${data.property_name} ===`);
    console.log('Alle Felder:', allFields.join(', '));

    // Finde Distanz-Feld (suche nach "distanz" im Feldnamen)
    let distanzSelect = null;
    let distanzFieldName = null;

    for (const key of Object.keys(data)) {
      if (key.startsWith('property_') && key.toLowerCase().includes('distanz')) {
        distanzSelect = data[key];
        distanzFieldName = key;
        console.log(`→ Distanz-Feld gefunden: ${key} = ${JSON.stringify(distanzSelect)}`);
        break;
      }
    }

    let maxDistanz = 50; // Default falls nicht gesetzt

    if (distanzSelect) {
      const match = String(distanzSelect).match(/\d+/);
      if (match) {
        maxDistanz = parseInt(match[0]);
      }
    }

    console.log(`→ Verwendete Distanz: ${maxDistanz}km\n`);

    addressItems.push({
      json: {
        id: data.id,
        name: data.property_name,
        phone: data.property_handynummer || null,
        address: data.property_wohnadresse,
        max_distanz_km: maxDistanz,
        type: 'kandidat'
      }
    });
  }
  // FACHGESCHÄFT
  else if (!data.property_geburtsdatum && data.property_adresse && data.property_adresse.trim() !== '') {
    addressItems.push({
      json: {
        id: data.id,
        name: data.property_name,
        address: data.property_adresse,
        type: 'fachgeschaeft'
      }
    });
  }
}

return addressItems;

const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const response = items[i].json;
  const originalItem = $('📍 Adressen + Distanz extrahieren').all()[i].json;

  if (response.status === 'OK' && response.results && response.results.length > 0) {
    const location = response.results[0].geometry.location;
    results.push({
      json: {
        id: originalItem.id,
        name: originalItem.name,
        phone: originalItem.phone,
        address: originalItem.address,
        max_distanz_km: originalItem.max_distanz_km,
        type: originalItem.type,
        lat: location.lat,
        lng: location.lng,
        geocoded: true
      }
    });
  } else {
    results.push({
      json: {
        id: originalItem.id,
        name: originalItem.name,
        phone: originalItem.phone,
        address: originalItem.address,
        max_distanz_km: originalItem.max_distanz_km,
        type: originalItem.type,
        geocoded: false
      }
    });
  }
}

return results;

const allItems = $input.first().json.data;

const kandidaten = allItems.filter(item => item.type === 'kandidat' && item.geocoded);
const fachgeschaefte = allItems.filter(item => item.type === 'fachgeschaeft' && item.geocoded);

if (kandidaten.length === 0 || fachgeschaefte.length === 0) {
  return [{ json: { error: 'Keine gültigen Kandidaten oder Fachgeschäfte' } }];
}

function calculateDistance(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat/2) * Math.sin(dLat/2) +
            Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
            Math.sin(dLon/2) * Math.sin(dLon/2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
  return R * c;
}

const ergebnisse = [];

for (const kandidat of kandidaten) {
  // INDIVIDUELLE DISTANZ PRO KANDIDAT!
  const maxDistanzKm = kandidat.max_distanz_km || 50;

  console.log(`=== ${kandidat.name}: 0-${maxDistanzKm} km ===`);

  const naheGeschafte = [];

  for (const geschaeft of fachgeschaefte) {
    const distanz = calculateDistance(
      kandidat.lat, kandidat.lng,
      geschaeft.lat, geschaeft.lng
    );
    const distanzGerundet = Math.round(distanz * 10) / 10;

    if (distanz <= maxDistanzKm) {
      naheGeschafte.push({
        id: geschaeft.id,
        name: geschaeft.name,
        distanz: distanzGerundet
      });
    }
  }

  naheGeschafte.sort((a, b) => a.distanz - b.distanz);

  if (naheGeschafte.length > 0) {
    ergebnisse.push({
      json: {
        kandidat_id: kandidat.id,
        kandidat_name: kandidat.name,
        kandidat_phone: kandidat.phone,
        fachgeschaefte_ids: naheGeschafte.map(g => g.id),
        fachgeschaefte_namen: naheGeschafte.map(g => g.name),
        distanzen_km: naheGeschafte.map(g => g.distanz),
        anzahl: naheGeschafte.length,
        naechstes_geschaeft: naheGeschafte[0].name,
        naechste_distanz_km: naheGeschafte[0].distanz
      }
    });
  }
}

console.log(`${ergebnisse.length} Kandidaten mit Zuordnungen`);

if (ergebnisse.length === 0) {
  return [{ json: { info: 'Keine Kandidaten im gewählten Distanz-Bereich' } }];
}

return ergebnisse;

// Notion Payload vorbereiten
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  // Skip Error/Info items
  if (data.error || data.info || !data.fachgeschaefte_namen) {
    console.log('Skipping item:', data);
    continue;
  }

  // Kommentar-Text erstellen
  const kommentarLines = data.fachgeschaefte_namen.map((name, i) => 
    `${i+1}. ${name}: ${data.distanzen_km[i]} km`
  );
  const kommentarText = 'Zugeordnete Geschäfte:\n' + kommentarLines.join('\n');

  // Notion Payload erstellen
  const notionPayload = {
    properties: {
      'zukünftiger Arbeitgeber': {
        relation: data.fachgeschaefte_ids.map(id => ({ id }))
      },
      'Distanz Wohnort zukünftiger Arbeitgeber': {
        number: data.naechste_distanz_km
      },
      'Kommentar': {
        rich_text: [{
          type: 'text',
          text: {
            content: kommentarText
          }
        }]
      }
    }
  };

  results.push({
    json: {
      kandidat_id: data.kandidat_id,
      notion_payload: JSON.stringify(notionPayload)
    }
  });
}

return results;
